/* =========================================================
   GUIDE HELPERS
========================================================= */

function getHeroGuide(heroName){

    if(!heroName){
        return null;
    }

    const key =
        heroName
            .trim()
            .toUpperCase();

    return d2ptGuides[key] || null;
}


/* Проверяем, заполнен ли гайд */

function hasHeroGuide(heroName){

    const guide =
        getHeroGuide(heroName);

    if(!guide){
        return false;
    }

    return Object.keys(guide).length > 0;
}


/* Возвращает список доступных ролей */

function getHeroGuideRoles(heroName){

    const guide =
        getHeroGuide(heroName);

    if(
        !guide ||
        !guide.builds
    ){
        return [];
    }

    return Object.keys(
        guide.builds
    );
}


/* =========================================================
   EXPORT TO ROSHAN
========================================================= */

window.d2ptGuides =
    d2ptGuides;

window.getHeroGuide =
    getHeroGuide;

window.hasHeroGuide =
    hasHeroGuide;

window.getHeroGuideRoles =
    getHeroGuideRoles;

window.D2PT_PATCH =
    D2PT_PATCH;
